create table if not exists public.diet_state (user_id uuid primary key references auth.users(id) on delete cascade,payload jsonb not null default '{"daily":{},"meals":[],"plans":[]}'::jsonb,updated_at timestamptz not null default now());alter table public.diet_state enable row level security;create policy "own select" on public.diet_state for select using (auth.uid()=user_id);create policy "own insert" on public.diet_state for insert with check (auth.uid()=user_id);create policy "own update" on public.diet_state for update using (auth.uid()=user_id) with check (auth.uid()=user_id);